use sotf_plugins::layout_solver::SolvedLayout;
use sotf_plugins::plugin_layout::*;

/// Information about a detected mode-selector group within `layout.main`.
pub(super) struct ModeSelectorInfo {
    /// Index into `layout.main` of the untitled ButtonSet group.
    pub(super) main_idx: usize,
    /// PARAMS index of the Choice param driving the selector.
    pub(super) param_idx: usize,
    /// Choice labels (also used to identify exclusive group titles).
    pub(super) labels: &'static [&'static str],
}

#[derive(Clone, Copy)]
pub(super) enum LayoutTabContent {
    Controls(&'static [ControlSpec]),
    Group(&'static ControlGroup),
}

pub(super) struct LayoutTab {
    pub(super) name: &'static str,
    pub(super) content: LayoutTabContent,
}

/// Collect all tabs: explicit LAYOUT tabs + collapsed column content.
pub(super) fn collect_all_tabs(
    layout: &'static PluginLayout,
    _solved: &SolvedLayout,
    overflow_groups: &[&'static ControlGroup],
) -> Vec<LayoutTab> {
    let mut tabs: Vec<LayoutTab> = Vec::new();

    // Explicit tabs from the layout
    for tab in layout.tabs {
        tabs.push(LayoutTab {
            name: tab.name,
            content: LayoutTabContent::Controls(tab.controls),
        });
    }

    for group in overflow_groups {
        if !group.title.is_empty() {
            tabs.push(LayoutTab {
                name: group.title,
                content: LayoutTabContent::Group(group),
            });
        }
    }

    tabs
}
